    /**
     * Filled silhouettes traced from the user-provided PDF03A page 34 JPEG (xref 71),
     * 850 x 1850 source pixels. These three glyphs are not Lucide geometry.
     * Threshold: max(R,G,B) < 128; marching-squares contour at 0.5, no path simplification.
     * EvenOdd preserves eye and cube negative space; callers supply the live palette tint.
     */
    private fun pdfCoreSilhouette(name: String, outline: String): ImageVector = ImageVector.Builder(
        name = "HetuPdf03A34.$name", defaultWidth = 40.dp, defaultHeight = 40.dp,
        viewportWidth = 86f, viewportHeight = 86f,
    ).apply {
        addPath(pathData = PathParser().parsePathString(outline).toNodes(),
            fill = SolidColor(Color.Black), pathFillType = PathFillType.EvenOdd)
    }.build()

